sp_widget.client_script:
/**
 * CLM APPROVER DASHBOARD — Client Script (FIXED)
 * Fix: calls refreshRequests() on init to load data from server
 */

api.controller = function($scope) {
    var c = this;

    // ── Init — don't override server data with empty arrays ────
    c.data.filteredRequests = [];
    c.data.selectedRequest  = null;
    c.data.deciding         = false;
    c.data.decisionDone     = false;
    c.data.filterSegment    = '';
    c.data.filterType       = '';
    c.data.filterDeviation  = '';
    c.data.decisionError    = '';
    c.data.refreshing       = false;
    c.data.lastRefreshed    = '';

    // ── Build filtered list from whatever requests exist ───────
    c.applyFilters = function() {
        var seg = c.data.filterSegment   || '';
        var typ = c.data.filterType      || '';
        var dev = c.data.filterDeviation || '';

        c.data.filteredRequests = (c.data.requests || []).filter(function(req) {
            if (seg && req.segment       !== seg)         return false;
            if (typ && req.customer_type !== typ)         return false;
            if (dev === 'deviation' && !req.is_deviation) return false;
            if (dev === 'standard'  &&  req.is_deviation) return false;
            return true;
        });
    };

    // Watch filters
    $scope.$watch(function() { return c.data.filterSegment;   }, function() { c.applyFilters(); });
    $scope.$watch(function() { return c.data.filterType;      }, function() { c.applyFilters(); });
    $scope.$watch(function() { return c.data.filterDeviation; }, function() { c.applyFilters(); });

    // ── KEY FIX: Load requests on init ─────────────────────────
    // Server sends data on page load via data.requests
    // But we also call refresh explicitly to ensure fresh data
    if (c.data.requests && c.data.requests.length > 0) {
        // Server already returned data on initial load
        c.applyFilters();
        c.data.lastRefreshed = new Date().toLocaleTimeString();
    } else {
        // Server returned empty — call refresh explicitly
        c.refreshRequests();
    }

    // ── Refresh ────────────────────────────────────────────────
    c.refreshRequests = function() {
        c.data.refreshing = true;
        c.server.get({ action: 'refresh' })
        .then(function(r) {
            c.data.refreshing    = false;
            c.data.lastRefreshed = new Date().toLocaleTimeString();
            if (r.data.requests) {
                c.data.requests = r.data.requests;
            } else {
                c.data.requests = [];
            }
            c.applyFilters();
        }).catch(function() {
            c.data.refreshing = false;
            c.data.requests   = c.data.requests || [];
            c.applyFilters();
        });
    };

    // ── Open detail ────────────────────────────────────────────
    c.openRequest = function(req) {
        c.data.selectedRequest  = req;
        c.data.decisionComments = '';
        c.data.approvedLimit    = null;
        c.data.decisionError    = '';
        c.data.decisionAction   = '';
    };

    c.closeRequest = function() {
        c.data.selectedRequest = null;
        c.data.decisionError   = '';
    };

    // ── Decide ─────────────────────────────────────────────────
    c.decide = function(action) {
        if (action !== 'approve') {
            if (!c.data.decisionComments || c.data.decisionComments.trim().length < 5) {
                c.data.decisionError = 'Please add comments before '
                    + (action === 'return' ? 'returning' : 'rejecting') + '.';
                return;
            }
        }

        c.data.decisionError  = '';
        c.data.deciding       = true;
        c.data.decisionAction = action;

        c.server.get({
            action:         'decide',
            sys_id:         c.data.selectedRequest.sys_id,
            decision:       action,
            comments:       c.data.decisionComments || '',
            approved_limit: c.data.approvedLimit    || 0
        }).then(function(r) {
            c.data.deciding = false;
            if (r.data.success) {
                c.data.decisionDone    = true;
                c.data.lastDecision    = action;
                c.data.decisionDoneMsg = r.data.message;
                c.data.selectedRequest = null;

                // Remove from list
                var pid = r.data.processed_sys_id;
                c.data.requests = (c.data.requests || []).filter(function(req) {
                    return req.sys_id !== pid;
                });
                c.applyFilters();
            } else {
                c.data.decisionError = r.data.error || 'Action failed.';
            }
        }).catch(function() {
            c.data.deciding      = false;
            c.data.decisionError = 'Server error. Please try again.';
        });
    };

    c.backToDashboard = function() {
        c.data.decisionDone = false;
        c.data.lastDecision = '';
        // Refresh list after decision
        c.refreshRequests();
    };
};

sp_widget.css:
/* ============================================================
   CLM APPROVER DASHBOARD — CSS (UltraTech Cement Theme)
   FULLY RESPONSIVE + MOBILE OPTIMIZED
   ============================================================ */

.clm-approver {
  font-family: "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif;
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 0;
  color: #1a1a1a;
  box-sizing: border-box;
}

/* ── Header ── */
.clm-ap-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #000000;
  color: #fff;
  padding: 20px 28px;
  border-radius: 8px 8px 0 0;
  border-top: 4px solid #FFF21A;
  flex-wrap: wrap;
  gap: 12px;
}
.clm-ap-title {
  font-size: 20px;
  font-weight: 600;
}
.clm-ap-subtitle {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.65);
  margin-top: 3px;
  width: 100%;
}
.clm-ap-count-badge {
  background: #FFF21A;
  color: #000000;
  padding: 5px 14px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 700;
  margin-left: auto;
}

/* ── Loading ── */
.clm-ap-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 60px 28px;
  background: #fff;
  border: 1px solid #e0e6ed;
  border-top: none;
  color: #7f8c9a;
}
.clm-spinner {
  width: 20px;
  height: 20px;
  border: 2px solid #e0e6ed;
  border-top-color: #000000;
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* ── Empty ── */
.clm-ap-empty {
  text-align: center;
  padding: 60px 28px;
  background: #fff;
  border: 1px solid #e0e6ed;
  border-top: none;
  border-radius: 0 0 8px 8px;
}
.clm-ap-empty-icon {
  font-size: 40px;
  color: #FFF21A;
  margin-bottom: 12px;
}
.clm-ap-empty-title {
  font-size: 18px;
  font-weight: 600;
  color: #000000;
  margin-bottom: 6px;
}
.clm-ap-empty-sub {
  color: #7f8c9a;
}

/* ── Filters ── */
.clm-ap-filters {
  display: flex;
  gap: 16px;
  padding: 16px 20px;
  background: #f8f8f8;
  border-bottom: 1px solid #dde3ea;
  flex-wrap: wrap;
}
.clm-ap-filter-item {
  flex: 1;
  min-width: 140px;
}
.clm-ap-filter-item label {
  display: block;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  color: #7f8c9a;
  margin-bottom: 4px;
}
.clm-ap-select {
  width: 100%;
  padding: 7px 10px;
  border: 2px solid #000000;
  border-radius: 4px;
  font-size: 13px;
  background: #fff;
  color: #000000;
  font-weight: 500;
  box-sizing: border-box;
}
.clm-ap-select:focus {
  outline: none;
  border-color: #FFF21A;
  box-shadow: 0 0 0 2px rgba(255, 242, 26, 0.2);
}

/* ── List ── */
.clm-ap-list {
  background: #fff;
  border: 1px solid #e0e6ed;
  border-top: none;
  border-radius: 0 0 8px 8px;
  overflow: hidden;
}

/* ── Card ── */
.clm-ap-card {
  padding: 16px 20px;
  border-bottom: 1px solid #e8eef3;
  cursor: pointer;
  transition: background 0.1s, border-left 0.1s;
  border-left: 4px solid transparent;
}
.clm-ap-card:last-child {
  border-bottom: none;
}
.clm-ap-card:hover {
  background: #f9f9f9;
  border-left-color: #FFF21A;
}

.clm-ap-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 12px;
  gap: 8px;
}
.clm-ap-card-num {
  font-size: 12px;
  color: #7f8c9a;
  font-weight: 600;
  margin-bottom: 2px;
}
.clm-ap-card-name {
  font-size: 15px;
  font-weight: 700;
  color: #000000;
  flex: 1;
}
.clm-ap-card-right {
  display: flex;
  gap: 6px;
  align-items: center;
  flex-shrink: 0;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.clm-badge {
  display: inline-block;
  padding: 3px 9px;
  border-radius: 3px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}
.clm-badge-segment {
  background: #f0f0f0;
  color: #000000;
  border: 1px solid #000000;
}
.clm-badge-dev {
  background: #FFF21A;
  color: #000000;
  border: 1px solid #000000;
  font-weight: 700;
}
.clm-badge-std {
  background: #eafaf1;
  color: #1e8449;
  border: 1px solid #a9dfbf;
}

.clm-ap-card-metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  margin-bottom: 12px;
}
.clm-ap-metric {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 0 0 auto;
}
.clm-ap-metric-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #7f8c9a;
}
.clm-ap-metric-value {
  font-size: 14px;
  font-weight: 600;
  color: #000000;
}

.clm-ap-card-footer {
  display: flex;
  gap: 20px;
  font-size: 12px;
  color: #a0aab4;
  flex-wrap: wrap;
}
.clm-ap-footer-cta {
  margin-left: auto;
  color: #000000;
  font-weight: 700;
}

/* ── Detail view ── */
.clm-ap-detail {
  background: #fff;
  border: 1px solid #e0e6ed;
  border-top: none;
  border-radius: 0 0 8px 8px;
  overflow: hidden;
}
.clm-ap-detail-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 20px;
  background: #f8f8f8;
  border-bottom: 2px solid #FFF21A;
  flex-wrap: wrap;
}
.clm-back-btn {
  background: #fff;
  border: 2px solid #000000;
  padding: 6px 12px;
  border-radius: 4px;
  font-size: 13px;
  color: #000000;
  cursor: pointer;
  white-space: nowrap;
  font-weight: 600;
  flex-shrink: 0;
}
.clm-back-btn:hover {
  background: #f0f0f0;
}
.clm-ap-detail-title {
  font-size: 16px;
  font-weight: 700;
  color: #000000;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  width: 100%;
}

/* Summary row */
.clm-ap-summary-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  border-bottom: 2px solid #FFF21A;
}
.clm-ap-summary-card {
  flex: 1;
  min-width: 120px;
  padding: 14px 16px;
  border-right: 1px solid #e0e6ed;
  text-align: center;
}
.clm-ap-summary-card:last-child {
  border-right: none;
}
.clm-summary-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  color: #7f8c9a;
  margin-bottom: 6px;
}
.clm-summary-value {
  font-size: 18px;
  font-weight: 700;
  color: #000000;
}
.clm-summary-ok {
  background: #f0f8f0;
  border-left: 4px solid #FFF21A;
}
.clm-summary-danger {
  background: #fff0f0;
  border-left: 4px solid #FFF21A;
}

/* Detail body */
.clm-ap-detail-body {
  display: flex;
  gap: 0;
}
.clm-ap-detail-left {
  flex: 1;
  border-right: 1px solid #e0e6ed;
  min-width: 0;
}
.clm-ap-detail-right {
  flex: 1.5;
  min-width: 0;
}

.clm-ap-detail-section {
  padding: 20px;
  border-bottom: 1px solid #e8eef3;
}
.clm-ap-detail-section:last-child {
  border-bottom: none;
}
.clm-ap-detail-section-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: #000000;
  margin-bottom: 14px;
  border-bottom: 2px solid #FFF21A;
  padding-bottom: 8px;
}

.clm-ap-kv-row {
  display: flex;
  justify-content: space-between;
  padding: 6px 0;
  border-bottom: 1px solid #f0f4f8;
  font-size: 13px;
  gap: 12px;
}
.clm-ap-kv-row:last-child {
  border-bottom: none;
}
.clm-ap-kv-key {
  color: #7f8c9a;
  font-weight: 600;
  flex: 0 0 40%;
}
.clm-ap-kv-val {
  font-weight: 600;
  color: #000000;
  text-align: right;
  flex: 1;
}

/* Aging bars */
.clm-aging-bar-wrap {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.clm-aging-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}
.clm-aging-label {
  width: 130px;
  flex-shrink: 0;
  color: #5a6a7a;
}
.clm-aging-bar-bg {
  flex: 1;
  height: 10px;
  background: #f0f4f8;
  border-radius: 5px;
  overflow: hidden;
}
.clm-aging-bar {
  height: 100%;
  border-radius: 5px;
  transition: width 0.4s;
  min-width: 2px;
}
.clm-aging-safe {
  background: #FFF21A;
}
.clm-aging-warn {
  background: #f39c12;
}
.clm-aging-crit {
  background: #e67e22;
}
.clm-aging-toxic {
  background: #e74c3c;
}
.clm-aging-pct {
  width: 40px;
  text-align: right;
  font-weight: 600;
  color: #5a6a7a;
  flex-shrink: 0;
}

/* Justification text */
.clm-ap-justification-text {
  font-size: 14px;
  line-height: 1.6;
  color: #000000;
  background: #f9f9f9;
  border: 2px solid #000000;
  border-radius: 5px;
  padding: 12px;
  white-space: pre-line;
  word-wrap: break-word;
  overflow-x: auto;
}
.clm-justification-dev {
  background: #fffbf0;
  border-color: #FFF21A;
}

/* Decision section */
.clm-ap-decision-section {
  background: #f8f8f8;
}
.clm-ap-decision-field {
  margin-bottom: 12px;
}
.clm-ap-decision-field label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: #000000;
  margin-bottom: 6px;
}
.clm-ap-input,
.clm-ap-textarea {
  width: 100%;
  padding: 9px 12px;
  border: 2px solid #000000;
  border-radius: 5px;
  font-size: 14px;
  box-sizing: border-box;
}
.clm-ap-input:focus,
.clm-ap-textarea:focus {
  outline: none;
  border-color: #FFF21A;
  box-shadow: 0 0 0 3px rgba(255, 242, 26, 0.2);
}
.clm-ap-textarea {
  resize: vertical;
  min-height: 70px;
}

.clm-ap-decision-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.clm-btn {
  padding: 10px 20px;
  border-radius: 5px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.15s;
  flex: 1;
  min-width: 120px;
}
.clm-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.clm-btn-approve {
  background: #000000;
  color: #FFF21A;
  border: 2px solid #000000;
}
.clm-btn-approve:hover:not(:disabled) {
  background: #FFF21A;
  color: #000000;
}
.clm-btn-return {
  background: #f39c12;
  color: #fff;
}
.clm-btn-return:hover:not(:disabled) {
  background: #d68910;
}
.clm-btn-reject {
  background: #e74c3c;
  color: #fff;
}
.clm-btn-reject:hover:not(:disabled) {
  background: #c0392b;
}
.clm-btn-outline {
  background: transparent;
  color: #000000;
  border: 2px solid #000000;
}
.clm-btn-outline:hover:not(:disabled) {
  background: #f0f0f0;
}

/* Done panel */
.clm-ap-done {
  text-align: center;
  padding: 60px 28px;
  background: #fff;
  border: 1px solid #e0e6ed;
  border-top: none;
  border-radius: 0 0 8px 8px;
}
.clm-ap-done-icon {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  font-size: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}
.clm-done-approved {
  background: #000000;
  color: #FFF21A;
}
.clm-done-returned {
  background: #f39c12;
  color: #fff;
}
.clm-done-rejected {
  background: #e74c3c;
  color: #fff;
}
.clm-ap-done h3 {
  font-size: 20px;
  color: #000000;
  margin-bottom: 10px;
}
.clm-ap-done p {
  color: #7f8c9a;
  margin-bottom: 24px;
}

/* Shared value states */
.clm-val-ok {
  color: #000000 !important;
}
.clm-val-warn {
  color: #f39c12 !important;
}
.clm-val-danger {
  color: #e74c3c !important;
}
.req {
  color: #FFF21A;
}

/* Refresh button */
.clm-refresh-btn {
  background: #FFF21A;
  border: 2px solid #000000;
  color: #000000;
  padding: 7px 16px;
  border-radius: 5px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s;
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.clm-refresh-btn:hover:not(:disabled) {
  background: #000000;
  color: #FFF21A;
}
.clm-refresh-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Spin animation for refresh icon */
.clm-spin {
  display: inline-block;
  animation: spin 0.7s linear infinite;
}

/* Last refreshed timestamp */
.clm-ap-refreshed {
  font-size: 11px;
  color: #7f8c9a;
  padding: 6px 20px;
  background: #f8f8f8;
  border-bottom: 1px solid #e0e6ed;
  border-left: 1px solid #e0e6ed;
  border-right: 1px solid #e0e6ed;
  text-align: right;
  border-top: 2px solid #FFF21A;
}

/* Customer type pills on cards */
.clm-type-pill {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.3px;
  margin-left: 4px;
  vertical-align: middle;
}
.clm-pill-trade {
  background: #f0f0f0;
  color: #000000;
  border: 1px solid #000000;
}
.clm-pill-nontrade {
  background: #FFF21A;
  color: #000000;
  font-weight: 700;
}
.clm-pill-key {
  background: #000000;
  color: #FFF21A;
}
.clm-pill-tool {
  background: #eaf4fb;
  color: #1a5276;
  border: 1px solid #aed6f1;
}
.clm-pill-nontool {
  background: #FFF21A;
  color: #000000;
  border: 1px solid #000000;
}

/* Summary sub-label */
.clm-summary-sub {
  font-size: 10px;
  color: #aab4be;
  margin-top: 3px;
}

/* No filter results */
.clm-ap-no-filter {
  padding: 24px;
  text-align: center;
  color: #aab4be;
  font-size: 14px;
}

/* ============================================================
   FORCE FULL-WIDTH APPROVER DASHBOARD (ServiceNow Override)
   ============================================================ */

.sn-widget-content,
.sn-widget-content > div,
.container,
.container-fluid {
  width: 100% !important;
  max-width: 100% !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
}

html,
body {
  width: 100%;
}

/* Inner padding for full-width layout */
.clm-ap-header,
.clm-ap-refreshed,
.clm-ap-filters,
.clm-ap-list,
.clm-ap-detail,
.clm-ap-done {
  padding-left: 24px;
  padding-right: 24px;
}

/* ============================================================
   TABLET BREAKPOINT — 768px
   ============================================================ */

@media (max-width: 768px) {
  .clm-ap-header {
    padding: 16px 20px;
  }

  .clm-ap-title {
    font-size: 18px;
  }

  .clm-ap-subtitle {
    font-size: 12px;
  }

  .clm-ap-count-badge {
    padding: 4px 12px;
    font-size: 12px;
  }

  .clm-ap-filters {
    padding: 12px 16px;
    gap: 12px;
  }

  .clm-ap-filter-item {
    flex: 0 0 calc(50% - 6px);
    min-width: unset;
  }

  .clm-ap-card {
    padding: 14px 16px;
  }

  .clm-ap-card-metrics {
    gap: 16px;
  }

  .clm-ap-card-footer {
    gap: 12px;
    font-size: 11px;
  }

  .clm-ap-detail-body {
    flex-direction: column;
  }

  .clm-ap-detail-left {
    border-right: none;
