sp_widget.script:
(function() {

    var action = input && input.action;
    var currentUser = gs.getUserID();

    function loadRequests() {
        var results = [];

        // First, get all pending approvals for the current user
        var approverGr = new GlideRecord('sysapproval_approver');
        approverGr.addQuery('approver', currentUser);
        approverGr.addQuery('state', 'requested');
        approverGr.addQuery('source_table', 'x_birl3_clm_clm_new_credit_request');
        approverGr.query();

        var requestSysIds = [];
        while (approverGr.next()) {
            var docId = approverGr.document_id + '';
            if (requestSysIds.indexOf(docId) === -1) {
                requestSysIds.push(docId);
            }
        }

        gs.info('CLM Dashboard: Found ' + requestSysIds.length + ' approval requests for user ' + currentUser);

        // If no approvals found, return empty
        if (requestSysIds.length === 0) {
            return results;
        }

        // Now get the actual credit requests
        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        gr.addQuery('sys_id', 'IN', requestSysIds.join(','));
        gr.orderByDesc('sys_created_on');
        gr.query();

        while (gr.next()) {
            var custSysId = gr.customer + '';
            var custName  = '';
            var custCode  = '';

            var cGr = new GlideRecord('x_birl3_clm_clm_customer_master1');
            if (custSysId && cGr.get(custSysId)) {
                custName = cGr.customer_name    + '';
                custCode = cGr.customer_code_sap + '';
            } else {
                custName = gr.customer.getDisplayValue() || 'Unknown';
                custCode = 'N/A';
            }

            var initiatorName = '';
            var iGr = new GlideRecord('sys_user');
            if (iGr.get(gr.initiator + '')) initiatorName = iGr.name + '';
            if (!initiatorName) initiatorName = gr.initiator.getDisplayValue() || 'Unknown';

            var total=0, safe=0, warning=0, critical=0, toxic=0, mCount=0;
            var agGr = new GlideRecord('x_birl3_clm_clm_aging_snapshot');
            agGr.addQuery('customer', custSysId);
            agGr.orderByDesc('snapshot_month');
            agGr.setLimit(6);
            agGr.query();

            while (agGr.next()) {
                mCount++;
                total    += parseFloat(agGr.total_outstanding)   || 0;
                safe     += (parseFloat(agGr.bucket_0_30_days)   || 0)
                          + (parseFloat(agGr.bucket_31_45_days)  || 0)
                          + (parseFloat(agGr.bucket_46_60_days)  || 0);
                warning  += parseFloat(agGr.bucket_61_75_days)   || 0;
                critical += parseFloat(agGr.bucket_76_90_days)   || 0;
                toxic    += (parseFloat(agGr.bucket_91_120_days) || 0)
                          + (parseFloat(agGr.bucket_gt120_days)  || 0);
            }

            var agingDetail = null;
            if (total > 0) {
                agingDetail = {
                    safe_pct:  Math.round((safe  / total) * 100),
                    warn_pct:  Math.round((warning / total) * 100),
                    crit_pct:  Math.round((critical / total) * 100),
                    toxic_pct: Math.round((toxic / total) * 100)
                };
            }

            var reviewDateStr = '';
            try { reviewDateStr = gr.next_review_date.getDisplayValue() || ''; } catch(e) {}

            // Get Trade-specific fields
            var requestedLimit = parseFloat(gr.requested_limit) || 0;
            var activeSD = parseFloat(gr.active_sd) || 0;
            var netExposure = parseFloat(gr.net_exposure) || 0;
            var maxAllowable = parseFloat(gr.max_allowable_limit) || 0;

            // Get Non-Trade/Key specific fields
            var p1Macl = parseFloat(gr.p1_macl) || 0;
            var p2Composite = parseFloat(gr.p2_composite) || 0;
            var p3Credit = parseFloat(gr.p3_credit) || 0;
            var safeLimit = parseFloat(gr.safe_limit) || 0;

            results.push({
                sys_id:                  gr.sys_id + '',
                number:                  gr.request_number + '',
                customer_name:           custName,
                customer_code:           custCode,
                customer_type:           gr.customer_type + '',
                segment:                 gr.segment + '',
                requested_limit:         requestedLimit / 100000,
                active_sd:               activeSD / 100000,
                net_exposure:            netExposure / 100000,
                max_allowable:           maxAllowable / 100000,
                system_mult:             gr.system_multiplier + '',
                implied_mult:            parseFloat(gr.implied_multiplier)  || 0,
                is_deviation:            gr.is_deviation + '' === 'true',
                nod:                     parseFloat(gr.nod_days)            || 0,
                aging_rating:            gr.aging_rating + '',
                aging_detail:            agingDetail,
                vintage_days:            parseInt(gr.customer_vintage_days) || 0,
                cheque_bounces:          parseInt(gr.cheque_bounces_12m)    || 0,
                market_perception:       gr.market_perception + '',
                justification:           gr.business_justification + '',
                deviation_justification: gr.deviation_justification + '',
                review_date:             reviewDateStr,
                initiator:               initiatorName,
                approver_role:           gr.required_approver_level + '',
                created:                 gr.sys_created_on.getDisplayValue(),
                // Non-Trade/Key fields
                p1_macl:                 p1Macl / 100000,
                p2_composite:            p2Composite,
                p3_credit:               p3Credit,
                safe_limit:              safeLimit / 100000,
                workflow_path:           gr.workflow_path + '',
                is_listed:               gr.is_listed + '' === 'true'
            });
        }

        gs.info('CLM Dashboard: Loaded ' + results.length + ' requests for approver ' + currentUser);
        return results;
    }

    // Helper: sync decision to sysapproval_approver for current user only
    function syncFlowApproval(requestSysId, decision, comments) {
        try {
            var apGr = new GlideRecord('sysapproval_approver');
            apGr.addQuery('source_table', 'x_birl3_clm_clm_new_credit_request');
            apGr.addQuery('document_id',  requestSysId);
            apGr.addQuery('approver', currentUser);
            apGr.addQuery('state', 'requested');
            apGr.query();

            var synced = 0;
            while (apGr.next()) {
                if (decision === 'approve') {
                    apGr.state    = 'approved';
                    apGr.comments = comments || 'Approved via CLM Dashboard';
                } else if (decision === 'reject') {
                    apGr.state    = 'rejected';
                    apGr.comments = comments || 'Rejected via CLM Dashboard';
                } else if (decision === 'return') {
                    apGr.state    = 'rejected';
                    apGr.comments = 'Returned to initiator: ' + (comments || '');
                }
                apGr.update();
                synced++;
                gs.info('CLM Dashboard: synced sysapproval_approver ' + apGr.sys_id + ' → ' + apGr.state + ' for user ' + currentUser);
            }

            if (synced === 0) {
                gs.warn('CLM Dashboard: no pending sysapproval_approver found for user ' + currentUser + ' and request ' + requestSysId);
            }

            return synced > 0;
        } catch(e) {
            gs.error('CLM Dashboard: syncFlowApproval error: ' + e.message);
            return false;
        }
    }

    // Check if all required approvals are complete
    function checkAllApprovalsComplete(requestSysId) {
        var apGr = new GlideRecord('sysapproval_approver');
        apGr.addQuery('source_table', 'x_birl3_clm_clm_new_credit_request');
        apGr.addQuery('document_id', requestSysId);
        apGr.addQuery('state', 'requested');
        apGr.query();

        return !apGr.hasNext();
    }

    // ── Refresh ───────────────────────────────────────────────
    if (action === 'refresh') {
        data.requests = loadRequests();
        return;
    }

    // ── Decision ──────────────────────────────────────────────
    if (action === 'decide') {
        // Security check: verify user is actually an approver for this request
        var verifyGr = new GlideRecord('sysapproval_approver');
        verifyGr.addQuery('source_table', 'x_birl3_clm_clm_new_credit_request');
        verifyGr.addQuery('document_id', input.sys_id);
        verifyGr.addQuery('approver', currentUser);
        verifyGr.addQuery('state', 'requested');
        verifyGr.query();

        if (!verifyGr.hasNext()) {
            data.success = false;
            data.error   = 'You are not authorized to approve this request or it has already been processed.';
            gs.warn('CLM Dashboard: Unauthorized/duplicate approval attempt by ' + currentUser + ' for request ' + input.sys_id);
            return;
        }

        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (!gr.get(input.sys_id)) {
            data.success = false;
            data.error   = 'Request not found.';
            return;
        }

        var requestNum = gr.request_number + '';
        var custName   = gr.customer.getDisplayValue();
        var comments   = input.comments || '';

        // Sync the current user's approval first
        var syncSuccess = syncFlowApproval(input.sys_id, input.decision, comments);

        if (!syncSuccess) {
            data.success = false;
            data.error = 'Failed to process approval. Please try again.';
            return;
        }

        if (input.decision === 'approve') {
            // Check if all approvals are complete
            var allComplete = checkAllApprovalsComplete(input.sys_id);

            if (allComplete) {
                // All approvers have approved - update main record
                gr.setWorkflow(false); // BYPASS ACL CHECK
                gr.state          = 'Approved';
                gr.approver       = currentUser;
                gr.approved_limit = (input.approved_limit && parseFloat(input.approved_limit) > 0)
                                  ? parseFloat(input.approved_limit) * 100000
                                  : parseFloat(gr.requested_limit);
                var rd = new GlideDateTime();
                rd.addMonthsUTC(12);
                gr.next_review_date     = rd.getDate();
                gr.sap_writeback_status = 'Pending';
                gr.update();

                data.success          = true;
                data.processed_sys_id = input.sys_id;
                data.message          = 'All approvals complete! ' + requestNum + ' fully approved for ' + custName
                    + '. Limit: ₹' + (parseFloat(gr.approved_limit) / 100000).toFixed(2) + 'L';
            } else {
                // Waiting for other approvers
                data.success          = true;
                data.processed_sys_id = input.sys_id;
                data.message          = 'Your approval recorded for ' + requestNum 
                    + '. Waiting for other approvers to complete.';
            }

        } else if (input.decision === 'return') {
            // Any approver can return - update main record immediately
            gr.setWorkflow(false); // BYPASS ACL CHECK
            gr.state           = 'Returned';
            gr.return_comments = comments;
            gr.approver        = currentUser;
            gr.update();

            data.success          = true;
            data.processed_sys_id = input.sys_id;
            data.message          = requestNum + ' returned to initiator.';

        } else if (input.decision === 'reject') {
            // Any approver can reject - update main record immediately
            gr.setWorkflow(false); // BYPASS ACL CHECK
            gr.state            = 'Rejected';
            gr.rejection_reason = comments;
            gr.approver         = currentUser;
            gr.update();

            data.success          = true;
            data.processed_sys_id = input.sys_id;
            data.message          = requestNum + ' rejected.';
        }
        return;
    }

    // Default load
    data.requests = loadRequests();

})();
